document.addEventListener("DOMContentLoaded",function(){let gf=document.querySelectorAll('.gform_wrapper');let fuelCAPTCHAObserver=new MutationObserver(function(mutations){mutations.forEach(function(mutation){document.addEventListener('keypress',fuelCAPTCHA_honeypot);window.addEventListener('mousemove',fuelCAPTCHA_honeypot)})});if(gf.length>0){fuelCAPTCHAObserver.observe(gf[0],{childList:!0});var xhr=new XMLHttpRequest();xhr.open('POST',fuelCAPTCHA_urls.ajax_url);xhr.setRequestHeader('Content-Type','application/x-www-form-urlencoded');xhr.send('action=fuelCAPTCHA_get_key');document.addEventListener('keypress',fuelCAPTCHA_honeypot);window.addEventListener('mousemove',fuelCAPTCHA_honeypot)}});function fuelCAPTCHA_honeypot(){document.removeEventListener('keypress',fuelCAPTCHA_honeypot);window.removeEventListener('mousemove',fuelCAPTCHA_honeypot);var reverseHoneypot=document.querySelectorAll('input[name=name-2]');for(var i=0;i<reverseHoneypot.length;i++){reverseHoneypot[i].setAttribute('value','')}}